import type { Readable } from 'node:stream';

/**
 * Where file bytes live. The rest of the app only talks to this interface,
 * so the local-disk implementation can later be swapped for S3 or any
 * S3-compatible object store without touching routes or services.
 *
 * Keys are always generated by the server (UUIDs) — never derived from
 * user input — so they cannot be used for path traversal.
 */
export interface StorageDriver {
  /** Moves a fully received temporary upload into permanent storage under `key`. */
  commitUpload(tempPath: string, key: string): Promise<void>;
  /**
   * Opens the stored bytes for streaming. Resolves only once the object is
   * open, so "missing object" errors surface before any response is sent.
   */
  openReadStream(key: string): Promise<Readable>;
  /** Deletes stored bytes. Must not throw if the object is already gone. */
  delete(key: string): Promise<void>;
  /** Directory where in-progress uploads are written before they are validated. */
  readonly tempDir: string;
  /** Prepares the storage (create directories, check access). */
  init(): Promise<void>;
}
